"""Enumeration of the refinement poset Ch(x, y) of chains from x to y."""

from __future__ import annotations
from typing import Callable, Dict, FrozenSet, List, Sequence, Tuple

Element = int
Chain = FrozenSet[Element]


def enumerate_chains(elements: Sequence[Element],
                     leq: Callable[[Element, Element], bool],
                     x: Element, y: Element) -> List[Chain]:
    """All chains from x to y, each produced exactly once.

    A chain from x to y is a finite totally ordered subset of the interval
    [x, y] containing both endpoints. Depth-first search extends the current
    partial chain by any element strictly above its last stop and still below y,
    so the sequence of stops is strictly increasing and no chain is repeated.
    Cost: O(|elements|) per emitted chain.
    """
    if not leq(x, y):
        return []
    if x == y:
        return [frozenset([x])]
    out: List[Chain] = []

    def extend(prefix: List[Element]) -> None:
        last = prefix[-1]
        if last == y:
            out.append(frozenset(prefix))
            return
        for t in elements:
            if t != last and leq(last, t) and leq(t, y):
                extend(prefix + [t])

    extend([x])
    return out


def count_chains(elements: Sequence[Element],
                 leq: Callable[[Element, Element], bool],
                 x: Element, y: Element) -> int:
    """|Ch(x, y)| without enumeration, via N(x,y) = sum_{x <= t < y} N(x,t)."""
    if not leq(x, y):
        return 0
    memo: Dict[Element, int] = {}

    def N(z: Element) -> int:
        if z == x:
            return 1
        if z not in memo:
            memo[z] = sum(N(t) for t in elements
                          if leq(x, t) and t != z and leq(t, z))
        return memo[z]

    return N(y)


def refinement_covers(chains: Sequence[Chain]) -> List[Tuple[Chain, Chain]]:
    """Covering pairs (C, D) of the refinement order: C subset D with |D| = |C| + 1."""
    return [(C, D) for C in chains for D in chains
            if len(D) == len(C) + 1 and C <= D]


def coarsest(x: Element, y: Element) -> Chain:
    """The least element of Ch(x, y): the two-element chain {x, y}."""
    return frozenset([x, y])


if __name__ == "__main__":
    # Boolean lattice B_3, chains from the empty set to the whole set.
    subsets = list(range(8))          # bitmasks
    leq = lambda a, b: (a & b) == a   # noqa: E731
    ch = enumerate_chains(subsets, leq, 0, 7)
    print("number of chains:", len(ch), "=", count_chains(subsets, leq, 0, 7))
    print("bottom is below all:", all(coarsest(0, 7) <= C for C in ch))
    print("covering pairs:", len(refinement_covers(ch)))

