function TOPOLOGICAL-ORDER(elements, leq):
    remaining <- list(elements); out <- []
    while remaining nonempty:
        pick a in remaining minimal for leq among remaining
        out.append(a); remaining.remove(a)
    return out

function MOBIUS-TABLE(elements, leq):               // O(n^3)
    for x in elements:
        for y in TOPOLOGICAL-ORDER(elements, leq):
            if not leq(x, y):   mu[x,y] <- 0
            else if x = y:      mu[x,y] <- 1
            else:               mu[x,y] <- - sum of mu[x,z] over x <= z < y
    return mu

function CHAIN-ALT-SUM(elements, leq, x, y):        // no enumeration
    memoised chi(z):
        if z = x: return -1
        return - sum of chi(t) over t with leq(x,t), t != z, leq(t,z)
    return 0 if not leq(x, y) else chi(y)

function VERIFY-HALL(elements, leq):
    mu <- MOBIUS-TABLE(elements, leq)
    return for all x, y:  CHAIN-ALT-SUM(elements, leq, x, y) = -mu[x,y]

