"""Moebius function two ways: alternating chain count, and the classical recursion.

Philip Hall's theorem says the two agree up to sign:
    sum over chains C from x to y of (-1)^|C|  =  -mu(x, y).
"""

from __future__ import annotations
from functools import lru_cache
from typing import Callable, Dict, List, Sequence, Tuple

Element = int


def mobius_table(elements: Sequence[Element],
                 leq: Callable[[Element, Element], bool]
                 ) -> Dict[Tuple[Element, Element], int]:
    """All values mu(x, y) by the recursion mu(x,y) = -sum_{x <= z < y} mu(x,z).

    Processing y along a linear extension makes every needed value available;
    total cost O(n^3) for n = |elements|.
    """
    order = topological_order(elements, leq)
    mu: Dict[Tuple[Element, Element], int] = {}
    for x in elements:
        for y in order:
            if not leq(x, y):
                mu[(x, y)] = 0
            elif x == y:
                mu[(x, y)] = 1
            else:
                mu[(x, y)] = -sum(mu[(x, z)] for z in elements
                                  if leq(x, z) and z != y and leq(z, y))
    return mu


def topological_order(elements: Sequence[Element],
                      leq: Callable[[Element, Element], bool]) -> List[Element]:
    """A linear extension of the order, by repeated extraction of minimal elements."""
    remaining = list(elements)
    out: List[Element] = []
    while remaining:
        for a in remaining:
            if all((not leq(b, a)) or b == a for b in remaining):
                out.append(a)
                remaining.remove(a)
                break
        else:                      # pragma: no cover - impossible for a poset
            raise ValueError("not a partial order")
    return out


def chain_alt_sum(elements: Sequence[Element],
                  leq: Callable[[Element, Element], bool],
                  x: Element, y: Element) -> int:
    """sum over chains from x to y of (-1)^|C|, computed by the decapitation
    recursion chi(x,y) = -sum_{x <= z < y} chi(x,z), chi(x,x) = -1.

    This is the signed form of the bijection 'delete the top element of the
    chain', which is exactly the induction used to prove Philip Hall's theorem;
    it avoids enumerating the (exponentially many) chains.
    """
    @lru_cache(maxsize=None)
    def chi(z: Element) -> int:
        if z == x:
            return -1
        return -sum(chi(t) for t in elements if leq(x, t) and t != z and leq(t, z))

    if not leq(x, y):
        return 0
    return chi(y)


def verify_hall(elements: Sequence[Element],
                leq: Callable[[Element, Element], bool]) -> bool:
    """Check sum_C (-1)^|C| = -mu(x, y) for every ordered pair."""
    mu = mobius_table(elements, leq)
    return all(chain_alt_sum(elements, leq, x, y) == -mu[(x, y)]
               for x in elements for y in elements)


if __name__ == "__main__":
    subsets = list(range(8))
    leq = lambda a, b: (a & b) == a   # noqa: E731
    print("Hall's theorem holds on B_3:", verify_hall(subsets, leq))
    print("alternating chain sum from bottom to top:",
          chain_alt_sum(subsets, leq, 0, 7),
          " -mu =", -mobius_table(subsets, leq)[(0, 7)])

