input: posets P subset Q, an order embedding f, endpoints x, y in P

function IS-ORDER-EMBEDDING(P, leqP, leqQ, f):
    return for all u, v in P:  leqP(u,v) = leqQ(f(u), f(v))

function TRANSPORT(f, C):   return { f(a) : a in C }
function TRACE(P, f, E):    return { a in P : f(a) in E }

function SPLIT(Ch_P, Ch_Q, P, f):
    image     <- { TRANSPORT(f, C) : C in Ch_P }
    remainder <- { E in Ch_Q : E not in image }
    assert for all C in Ch_P:  TRACE(P, f, TRANSPORT(f, C)) = C      // retraction
    adjunction <- for all C in Ch_P, E in Ch_Q:
                      (TRANSPORT(f,C) subset E)  iff  (C subset TRACE(P,f,E))
    lower <- for all E in image, E' in Ch_Q with E' subset E:  E' in image
    upper <- for all E in remainder, E' in Ch_Q with E subset E':  E' in remainder
    assert |image| + |remainder| = |Ch_Q|
    return (image, remainder, adjunction, lower, upper)
